-- Migration: 0133_create_web_chat.sql
-- Purpose: first-party anonymous visitor live chat — public website widget + staff console.
--
-- Design notes:
--   * Replaces the third-party live chat providers (Tawk.to / LiveChat / Zendesk) that the legacy
--     WHMCS theme embedded. No third-party chat provider is integrated; visitors talk only to
--     the CloudHost247 platform itself.
--   * `web_chat_conversations` — one row per anonymous visitor session. The visitor is identified
--     by an opaque random token generated by the server; ONLY sha256(token) is stored
--     (`visitor_token_hash`), so a database leak cannot impersonate a visitor.
--   * `web_chat_messages.seq` — monotonically increasing IDENTITY column. The widget and the
--     staff console poll `seq > after`, which is immune to identical-timestamp messages and
--     lets both sides resume cheaply.
--   * `author = 'staff'` rows carry the replying staff member's `users.id` (nullable — the
--     account survives staff deletion). `author = 'visitor'` rows carry no identity.
--   * Runs inside the migration runner's own transaction — no BEGIN/COMMIT.
--   * Local schema + CI; production rollout follows the normal migration gate.

CREATE TABLE IF NOT EXISTS web_chat_conversations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  visitor_token_hash text NOT NULL UNIQUE,
  visitor_name varchar(120) NULL,
  visitor_email varchar(255) NULL,
  status varchar(10) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
  source varchar(20) NOT NULL DEFAULT 'spa' CHECK (source IN ('spa', 'whmcs', 'unknown')),
  last_message_at timestamptz NULL,
  staff_read_at timestamptz NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT web_chat_conversations_email_check CHECK (
    visitor_email IS NULL OR length(btrim(visitor_email)) <= 255
  )
);

CREATE INDEX IF NOT EXISTS web_chat_conversations_status_idx
  ON web_chat_conversations (status, last_message_at DESC NULLS LAST);
CREATE INDEX IF NOT EXISTS web_chat_conversations_created_at_idx
  ON web_chat_conversations (created_at DESC);

CREATE TABLE IF NOT EXISTS web_chat_messages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  seq bigint GENERATED ALWAYS AS IDENTITY,
  conversation_id uuid NOT NULL REFERENCES web_chat_conversations (id) ON DELETE CASCADE,
  author varchar(10) NOT NULL CHECK (author IN ('visitor', 'staff')),
  author_id uuid NULL REFERENCES users (id) ON DELETE SET NULL,
  author_name varchar(120) NULL,
  body text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT web_chat_messages_body_check CHECK (
    length(btrim(body)) > 0 AND length(body) <= 4000
  )
);

CREATE UNIQUE INDEX IF NOT EXISTS web_chat_messages_seq_idx
  ON web_chat_messages (seq);
CREATE INDEX IF NOT EXISTS web_chat_messages_conversation_seq_idx
  ON web_chat_messages (conversation_id, seq);
